import { randomUUID } from 'crypto';
import type { PoolConnection } from 'mysql2/promise';
import { pool } from '../../config/database';
import { AppError } from '../../shared/errors/AppError';
import { AuditService } from '../../shared/audit/audit.service';
import { FinancePostingService } from '../../shared/finance/finance-posting.service';
import { jakartaBusinessDate, jakartaDateStartUtc, utcDateTimeSql } from '../../shared/time/jakarta-time';
import { unifiedFinanceAccess } from './finance-access.service';
import type { FinanceAccess, FinanceActor, FinanceFilters, FinancePeriod } from './finance.types';

const money = (value: unknown) => Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100;
const code = (prefix: string, id: number) => `${prefix}-${String(id).padStart(6, '0')}`;
const PAGE_CAP = 100;
const EXPORT_CAP = 20_000;
const placeholders = (values: unknown[]) => values.map(() => '?').join(',');
const utcSql = (date: Date) => utcDateTimeSql(date);
const ymd = (date: Date) => date.toISOString().slice(0, 10);
const addDays = (date: Date, days: number) => new Date(date.getTime() + days * 86_400_000);

type QueryContext = { access: FinanceAccess; filters: FinanceFilters; unitIds: number[]; period: FinancePeriod; currency: string };

function jakartaToday() { return new Date(`${jakartaBusinessDate()}T00:00:00.000Z`); }
function financialPeriod(filters: FinanceFilters): FinancePeriod {
  const today = jakartaToday(); let start = today; let end = today;
  if (filters.period === 'week') { const offset = (today.getUTCDay() + 6) % 7; start = addDays(today, -offset); end = addDays(start, 6); }
  if (filters.period === 'month') { start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1)); end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth() + 1, 0)); }
  if (filters.period === 'year') { start = new Date(Date.UTC(today.getUTCFullYear(), 0, 1)); end = new Date(Date.UTC(today.getUTCFullYear(), 11, 31)); }
  if (filters.period === 'custom') { start = new Date(`${filters.from}T00:00:00.000Z`); end = new Date(`${filters.to}T00:00:00.000Z`); if (end < start) throw new AppError(400, 'FINANCE_INVALID_RANGE', 'Tanggal akhir harus setelah tanggal mulai.'); }
  return { range: filters.period, start_date: ymd(start), end_date: ymd(end), start_at_utc: utcSql(jakartaDateStartUtc(ymd(start))), end_at_utc: utcSql(jakartaDateStartUtc(ymd(addDays(end, 1)))), timezone: 'Asia/Jakarta' };
}

function pageResult(items: any[], page: number, limit: number, total: number) { return { items, meta: { page, limit, total, totalPages: Math.max(1, Math.ceil(total / limit)) } }; }
function asMoneyRows(rows: any[]) { return rows.map(row => Object.fromEntries(Object.entries(row).map(([key, value]) => /amount|balance|cash|income|expense|result|paid|total|net|debit|credit|value|flow|budget/i.test(key) ? [key, money(value)] : [key, value]))); }

/** Consolidated reader/controller service. It consumes the canonical finance tables; it never materializes a second ledger. */
export class UnifiedFinanceService {
  private posting = new FinancePostingService();

  private async context(actor: FinanceActor, filters: FinanceFilters): Promise<QueryContext> {
    const access = await unifiedFinanceAccess.resolve(actor);
    const unitIds = unifiedFinanceAccess.ids(access, filters.workspace);
    const currencies: string[] = await this.currencies(access, unitIds.length ? unitIds : unifiedFinanceAccess.ids(access));
    const currency = filters.currency || currencies.find(item => item === 'IDR') || currencies[0] || 'IDR';
    return { access, filters, unitIds, period: financialPeriod(filters), currency };
  }

  private async currencies(access: FinanceAccess, ids: number[]) {
    if (!ids.length) return [] as string[];
    const [rows]: any = await pool.execute(
      `SELECT DISTINCT currency_code FROM (
         SELECT currency_code FROM treasury_accounts WHERE organization_id=? AND business_unit_id IN (${placeholders(ids)})
         UNION DISTINCT SELECT currency_code FROM financial_transactions WHERE organization_id=? AND business_unit_id IN (${placeholders(ids)}) AND status_code='posted'
       ) currencies WHERE currency_code IS NOT NULL ORDER BY currency_code`,
      [access.organizationId, ...ids, access.organizationId, ...ids],
    );
    return rows.map((row: any) => String(row.currency_code).toUpperCase());
  }

  private transactionWhere(ctx: QueryContext, alias = 'ft') {
    if (!ctx.unitIds.length) return { sql: ' WHERE 1=0', params: [] as unknown[] };
    let sql = ` WHERE ${alias}.organization_id=? AND ${alias}.business_unit_id IN (${placeholders(ctx.unitIds)})`;
    const params: any[] = [ctx.access.organizationId, ...ctx.unitIds];
    const add = (statement: string, ...values: unknown[]) => { sql += ` AND ${statement}`; params.push(...values); };
    add(`${alias}.transaction_date>=? AND ${alias}.transaction_date<?`, ctx.period.start_at_utc, ctx.period.end_at_utc);
    if (ctx.currency) add(`${alias}.currency_code=?`, ctx.currency);
    if (ctx.filters.transaction_type) add(`${alias}.transaction_type=?`, ctx.filters.transaction_type);
    if (ctx.filters.category) add(`tc.code=?`, ctx.filters.category);
    if (ctx.filters.treasury) add(`${alias}.treasury_account_id=?`, ctx.filters.treasury);
    if (ctx.filters.source) add(`${alias}.source_type=?`, ctx.filters.source);
    if (ctx.filters.status) add(`${alias}.status_code=?`, ctx.filters.status); else add(`${alias}.status_code='posted'`);
    if (ctx.filters.q) { const term = `%${ctx.filters.q}%`; add(`(${alias}.transaction_code LIKE ? OR ${alias}.description LIKE ? OR p.display_name LIKE ?)`, term, term, term); }
    return { sql, params };
  }

  private async classification(ctx: QueryContext, ids = ctx.unitIds) {
    if (!ids.length) return { income: 0, expense: 0, expense_reversal: 0, income_reversal: 0, cash_in: 0, cash_out: 0 };
    const [rows]: any = await pool.execute(
      `SELECT
       COALESCE(SUM(CASE WHEN ft.transaction_type='income' THEN ft.amount ELSE 0 END),0) income,
       COALESCE(SUM(CASE WHEN ft.transaction_type='expense' THEN ft.amount ELSE 0 END),0) expense,
       COALESCE(SUM(CASE WHEN ft.transaction_type='adjustment' AND (ft.source_type='studio_expense_reversal' OR (ft.source_type='finance_cash_reversal' AND original.transaction_type='expense')) THEN ft.amount ELSE 0 END),0) expense_reversal,
       COALESCE(SUM(CASE WHEN ft.transaction_type='adjustment' AND ft.source_type='finance_cash_reversal' AND original.transaction_type='income' THEN ft.amount ELSE 0 END),0) income_reversal
       FROM financial_transactions ft
       LEFT JOIN financial_transactions original ON original.id=ft.source_id AND ft.source_type='finance_cash_reversal'
       WHERE ft.organization_id=? AND ft.business_unit_id IN (${placeholders(ids)}) AND ft.status_code='posted'
         AND ft.transaction_date>=? AND ft.transaction_date<? AND ft.currency_code=?`,
      [ctx.access.organizationId, ...ids, ctx.period.start_at_utc, ctx.period.end_at_utc, ctx.currency],
    );
    const row = rows[0] || {}; const income = money(row.income); const expense = money(row.expense); const expenseReversal = money(row.expense_reversal); const incomeReversal = money(row.income_reversal);
    return { income, expense, expense_reversal: expenseReversal, income_reversal: incomeReversal, cash_in: money(income + expenseReversal), cash_out: money(expense + incomeReversal) };
  }

  private async cashSnapshot(ctx: QueryContext, ids = ctx.unitIds) {
    if (!ids.length) return 0;
    const [rows]: any = await pool.execute(`SELECT COALESCE(SUM(current_balance),0) total FROM treasury_accounts WHERE organization_id=? AND business_unit_id IN (${placeholders(ids)}) AND is_active=1 AND currency_code=?`, [ctx.access.organizationId, ...ids, ctx.currency]);
    return money(rows[0]?.total);
  }

  private async receivableTotal(ctx: QueryContext) {
    if (!ctx.unitIds.length) return 0;
    const [rows]: any = await pool.execute(`SELECT COALESCE(SUM(balance_due),0) total FROM invoices WHERE organization_id=? AND business_unit_id IN (${placeholders(ctx.unitIds)}) AND currency_code=? AND balance_due>0.005 AND status_code NOT IN ('void','refunded')`, [ctx.access.organizationId, ...ctx.unitIds, ctx.currency]);
    return money(rows[0]?.total);
  }

  private async payableTotal(ctx: QueryContext) {
    if (!ctx.unitIds.length) return 0;
    const [supplier, expenses, assignments]: any = await Promise.all([
      pool.execute(`SELECT COALESCE(SUM(balance_due),0) total FROM supplier_invoices WHERE business_unit_id IN (${placeholders(ctx.unitIds)}) AND currency_code=? AND balance_due>0.005 AND status_code NOT IN ('paid','void')`, [...ctx.unitIds, ctx.currency]),
      pool.execute(`SELECT COALESCE(SUM(amount+tax_amount),0) total FROM expenses WHERE organization_id=? AND business_unit_id IN (${placeholders(ctx.unitIds)}) AND currency_code=? AND status_code IN ('draft','approved')`, [ctx.access.organizationId, ...ctx.unitIds, ctx.currency]),
      pool.execute(`SELECT COALESCE(SUM(pea.agreed_fee-COALESCE(paid.paid_amount,0)),0) total FROM project_external_assignments pea JOIN studio_projects sp ON sp.id=pea.project_id AND sp.deleted_at IS NULL JOIN business_units bu ON bu.id=sp.business_unit_id LEFT JOIN (SELECT source_code,SUM(amount) paid_amount FROM financial_transactions WHERE organization_id=? AND source_type='studio_external_payout' AND status_code='posted' GROUP BY source_code) paid ON paid.source_code=CONCAT('ASSIGN-',pea.id) WHERE bu.organization_id=? AND bu.code='STUDIO' AND sp.business_unit_id IN (${placeholders(ctx.unitIds)}) AND sp.currency_code=?`, [ctx.access.organizationId, ctx.access.organizationId, ...ctx.unitIds, ctx.currency]),
    ]);
    return money(Number(supplier[0][0]?.total || 0) + Number(expenses[0][0]?.total || 0) + Number(assignments[0][0]?.total || 0));
  }

  async meta(actor: FinanceActor) {
    const access = await unifiedFinanceAccess.resolve(actor); const ids = unifiedFinanceAccess.ids(access);
    const [currencies, categories, treasuries]: any = await Promise.all([
      this.currencies(access, ids),
      ids.length ? pool.execute(`SELECT tc.id,tc.code,tc.name,tc.transaction_type,bu.code workspace FROM transaction_categories tc JOIN business_units bu ON bu.id=tc.business_unit_id WHERE tc.organization_id=? AND tc.business_unit_id IN (${placeholders(ids)}) AND tc.is_active=1 ORDER BY bu.code,tc.transaction_type,tc.name`, [access.organizationId, ...ids]) : Promise.resolve([[]]),
      ids.length ? pool.execute(`SELECT id,account_code,name,account_type,currency_code,current_balance,business_unit_id FROM treasury_accounts WHERE organization_id=? AND business_unit_id IN (${placeholders(ids)}) AND is_active=1 ORDER BY name`, [access.organizationId, ...ids]) : Promise.resolve([[]]),
    ]);
    return { workspaces: access.units.map(unit => ({ code: unit.code.toLowerCase(), name: unit.name, id: unit.id })), currencies: currencies.length ? currencies : ['IDR'], default_currency: currencies.includes('IDR') ? 'IDR' : currencies[0] || 'IDR', categories: categories[0], treasuries: asMoneyRows(treasuries[0]), permissions: [...access.permissions], can_create_shared_transaction: Boolean(access.byCode.SHARED && access.permissions.has('finance.write')), can_manage: access.permissions.has('finance.manage'), can_transfer: Boolean(access.byCode.SHARED && access.permissions.has('finance.transfer')) };
  }

  async overview(actor: FinanceActor, filters: FinanceFilters) {
    const ctx = await this.context(actor, filters);
    const [classification, cash, receivables, payables, transferRows] = await Promise.all([
      this.classification(ctx), this.cashSnapshot(ctx), this.receivableTotal(ctx), this.payableTotal(ctx), this.transferActivity(ctx),
    ]);
    const breakdown = await Promise.all(ctx.access.units.filter(unit => ctx.unitIds.includes(unit.id)).map(async unit => {
      const [unitCash, values] = await Promise.all([this.cashSnapshot(ctx, [unit.id]), this.classification(ctx, [unit.id])]);
      return { workspace: unit.code.toLowerCase(), currency_code: ctx.currency, cash: unitCash, income: values.income, expense: values.expense, net: money(values.income - values.expense + values.expense_reversal - values.income_reversal) };
    }));
    const netFlow = money(classification.cash_in - classification.cash_out);
    const operatingResult = money(classification.income - classification.expense + classification.expense_reversal - classification.income_reversal);
    return { currency_code: ctx.currency, period: ctx.period, accessible_workspaces: breakdown.map(row => row.workspace), metrics: {
      total_cash: { value: cash, currency_code: ctx.currency, snapshot: true, label: 'Total Kas Saat Ini' },
      period_income: { value: classification.income, currency_code: ctx.currency, snapshot: false }, period_expense: { value: classification.expense, currency_code: ctx.currency, snapshot: false },
      net_cash_flow: { value: netFlow, currency_code: ctx.currency, snapshot: false }, receivables: { value: receivables, currency_code: ctx.currency, snapshot: true }, payables: { value: payables, currency_code: ctx.currency, snapshot: true },
      operating_result: { value: operatingResult, currency_code: ctx.currency, snapshot: false, basis: 'basis transaksi kas' }, transfer_activity: transferRows,
    }, breakdown };
  }

  async transactions(actor: FinanceActor, filters: FinanceFilters) {
    const ctx = await this.context(actor, filters); const { sql, params } = this.transactionWhere(ctx); const page = filters.page; const limit = Math.min(PAGE_CAP, filters.limit); const offset = (page - 1) * limit;
    const joins = ' FROM financial_transactions ft JOIN business_units bu ON bu.id=ft.business_unit_id LEFT JOIN transaction_categories tc ON tc.id=ft.category_id LEFT JOIN treasury_accounts ta ON ta.id=ft.treasury_account_id LEFT JOIN parties p ON p.id=ft.party_id';
    const [rows, count]: any = await Promise.all([
      pool.execute(`SELECT ft.*,bu.code workspace,tc.code category_code,tc.name category_name,ta.name treasury_name,p.display_name party_name ${joins}${sql} ORDER BY ft.transaction_date DESC,ft.id DESC LIMIT ${limit} OFFSET ${offset}`, params),
      pool.execute(`SELECT COUNT(*) total ${joins}${sql}`, params),
    ]);
    return pageResult(asMoneyRows(rows[0]), page, limit, Number(count[0][0]?.total || 0));
  }

  async transaction(actor: FinanceActor, id: number) {
    const access = await unifiedFinanceAccess.resolve(actor); const ids = unifiedFinanceAccess.ids(access); if (!ids.length) throw new AppError(404, 'FINANCIAL_TRANSACTION_NOT_FOUND', 'Transaksi tidak ditemukan.');
    const [rows]: any = await pool.execute(`SELECT ft.*,bu.code workspace,tc.code category_code,tc.name category_name,ta.name treasury_name,p.display_name party_name FROM financial_transactions ft JOIN business_units bu ON bu.id=ft.business_unit_id LEFT JOIN transaction_categories tc ON tc.id=ft.category_id LEFT JOIN treasury_accounts ta ON ta.id=ft.treasury_account_id LEFT JOIN parties p ON p.id=ft.party_id WHERE ft.id=? AND ft.organization_id=? AND ft.business_unit_id IN (${placeholders(ids)}) LIMIT 1`, [id, access.organizationId, ...ids]);
    if (!rows.length) throw new AppError(404, 'FINANCIAL_TRANSACTION_NOT_FOUND', 'Transaksi tidak ditemukan.'); return asMoneyRows(rows)[0];
  }

  async treasury(actor: FinanceActor, filters: FinanceFilters) {
    const ctx = await this.context(actor, filters); if (!ctx.unitIds.length) return [];
    const [rows]: any = await pool.execute(`SELECT ta.id,ta.account_code,ta.name,ta.account_type,ta.provider_name,ta.account_number_masked,ta.currency_code,ta.current_balance,ta.opening_balance,ta.is_active,bu.code workspace,MAX(ft.transaction_date) last_transaction_at FROM treasury_accounts ta JOIN business_units bu ON bu.id=ta.business_unit_id LEFT JOIN financial_transactions ft ON ft.treasury_account_id=ta.id AND ft.status_code='posted' WHERE ta.organization_id=? AND ta.business_unit_id IN (${placeholders(ctx.unitIds)})${filters.currency ? ' AND ta.currency_code=?' : ''} GROUP BY ta.id ORDER BY FIELD(bu.code,'CRAFT','STUDIO','SHARED'),ta.name`, [ctx.access.organizationId, ...ctx.unitIds, ...(filters.currency ? [ctx.currency] : [])]);
    return asMoneyRows(rows);
  }

  private async transferActivity(ctx: QueryContext) {
    if (!ctx.unitIds.length) return { count: 0, amount: 0, currency_code: ctx.currency };
    const [rows]: any = await pool.execute(`SELECT COUNT(*) count,COALESCE(SUM(amount),0) amount FROM internal_transfers WHERE organization_id=? AND currency_code=? AND transfer_date>=? AND transfer_date<? AND status_code='completed' AND from_business_unit_id IN (${placeholders(ctx.unitIds)}) AND to_business_unit_id IN (${placeholders(ctx.unitIds)})`, [ctx.access.organizationId,ctx.currency,ctx.period.start_at_utc,ctx.period.end_at_utc,...ctx.unitIds,...ctx.unitIds]);
    return { count: Number(rows[0]?.count || 0), amount: money(rows[0]?.amount), currency_code: ctx.currency };
  }

  async transfers(actor: FinanceActor, filters: FinanceFilters) {
    const ctx = await this.context(actor, filters); if (!ctx.unitIds.length) return pageResult([], filters.page, filters.limit, 0);
    const page = filters.page; const limit = Math.min(PAGE_CAP, filters.limit); const offset = (page - 1) * limit;
    let where = ` WHERE t.organization_id=? AND t.from_business_unit_id IN (${placeholders(ctx.unitIds)}) AND t.to_business_unit_id IN (${placeholders(ctx.unitIds)})`; const params: any[] = [ctx.access.organizationId,...ctx.unitIds,...ctx.unitIds];
    where += ' AND t.transfer_date>=? AND t.transfer_date<?'; params.push(ctx.period.start_at_utc,ctx.period.end_at_utc); if (filters.currency) { where += ' AND t.currency_code=?'; params.push(ctx.currency); } if (filters.status) { where += ' AND t.status_code=?'; params.push(filters.status); } if (filters.q) { where += ' AND (t.transfer_code LIKE ? OR t.description LIKE ?)'; params.push(`%${filters.q}%`,`%${filters.q}%`); }
    const joins = ' FROM internal_transfers t JOIN business_units from_bu ON from_bu.id=t.from_business_unit_id JOIN business_units to_bu ON to_bu.id=t.to_business_unit_id JOIN treasury_accounts from_t ON from_t.id=t.from_treasury_account_id JOIN treasury_accounts to_t ON to_t.id=t.to_treasury_account_id';
    const [rows, count]: any = await Promise.all([pool.execute(`SELECT t.*,from_bu.code from_workspace,to_bu.code to_workspace,from_t.name from_treasury_name,to_t.name to_treasury_name ${joins}${where} ORDER BY t.transfer_date DESC,t.id DESC LIMIT ${limit} OFFSET ${offset}`,params),pool.execute(`SELECT COUNT(*) total ${joins}${where}`,params)]);
    return pageResult(asMoneyRows(rows[0]),page,limit,Number(count[0][0]?.total || 0));
  }

  async transfer(actor: FinanceActor, id: number) {
    const access = await unifiedFinanceAccess.resolve(actor); const ids = unifiedFinanceAccess.ids(access); if (!ids.length) throw new AppError(404,'TRANSFER_NOT_FOUND','Transfer tidak ditemukan.');
    const [rows]: any = await pool.execute(`SELECT t.*,from_bu.code from_workspace,to_bu.code to_workspace,from_t.name from_treasury_name,to_t.name to_treasury_name FROM internal_transfers t JOIN business_units from_bu ON from_bu.id=t.from_business_unit_id JOIN business_units to_bu ON to_bu.id=t.to_business_unit_id JOIN treasury_accounts from_t ON from_t.id=t.from_treasury_account_id JOIN treasury_accounts to_t ON to_t.id=t.to_treasury_account_id WHERE t.id=? AND t.organization_id=? AND t.from_business_unit_id IN (${placeholders(ids)}) AND t.to_business_unit_id IN (${placeholders(ids)}) LIMIT 1`,[id,access.organizationId,...ids,...ids]);
    if(!rows.length) throw new AppError(404,'TRANSFER_NOT_FOUND','Transfer tidak ditemukan.'); return asMoneyRows(rows)[0];
  }

  async cashFlow(actor: FinanceActor, filters: FinanceFilters) {
    const ctx = await this.context(actor, filters); if (!ctx.unitIds.length) return { currency_code: ctx.currency, period: ctx.period, cash_in: 0, cash_out: 0, net_cash_flow: 0, series: [], breakdown: [] };
    const duration = Math.round((new Date(`${ctx.period.end_date}T00:00:00Z`).getTime() - new Date(`${ctx.period.start_date}T00:00:00Z`).getTime()) / 86_400_000) + 1;
    const local = "CONVERT_TZ(ft.transaction_date,'+00:00','+07:00')"; const label = duration <= 45 ? `DATE_FORMAT(${local},'%Y-%m-%d')` : duration <= 180 ? `DATE_FORMAT(DATE_SUB(DATE(${local}), INTERVAL WEEKDAY(${local}) DAY),'%Y-%m-%d')` : `DATE_FORMAT(${local},'%Y-%m')`;
    const [rows, breakdown] : any = await Promise.all([
      pool.execute(`SELECT ${label} label,bu.code workspace,COALESCE(SUM(CASE WHEN ft.transaction_type='income' OR (ft.transaction_type='adjustment' AND (ft.source_type='studio_expense_reversal' OR (ft.source_type='finance_cash_reversal' AND original.transaction_type='expense'))) THEN ft.amount ELSE 0 END),0) cash_in,COALESCE(SUM(CASE WHEN ft.transaction_type='expense' OR (ft.transaction_type='adjustment' AND ft.source_type='finance_cash_reversal' AND original.transaction_type='income') THEN ft.amount ELSE 0 END),0) cash_out FROM financial_transactions ft JOIN business_units bu ON bu.id=ft.business_unit_id LEFT JOIN financial_transactions original ON original.id=ft.source_id AND ft.source_type='finance_cash_reversal' WHERE ft.organization_id=? AND ft.business_unit_id IN (${placeholders(ctx.unitIds)}) AND ft.status_code='posted' AND ft.currency_code=? AND ft.transaction_date>=? AND ft.transaction_date<? GROUP BY label,bu.code ORDER BY label`,[ctx.access.organizationId,...ctx.unitIds,ctx.currency,ctx.period.start_at_utc,ctx.period.end_at_utc]),
      Promise.all(ctx.access.units.filter(unit=>ctx.unitIds.includes(unit.id)).map(async unit=>({ workspace:unit.code.toLowerCase(), ...(await this.classification(ctx,[unit.id])) }))),
    ]);
    const series = asMoneyRows(rows[0]).map((row:any)=>({...row,net_cash_flow:money(row.cash_in-row.cash_out)})); const totals = series.reduce((sum:any,row:any)=>({cash_in:sum.cash_in+row.cash_in,cash_out:sum.cash_out+row.cash_out}),{cash_in:0,cash_out:0});
    return { currency_code:ctx.currency,period:ctx.period,cash_in:money(totals.cash_in),cash_out:money(totals.cash_out),net_cash_flow:money(totals.cash_in-totals.cash_out),series,breakdown:breakdown.map((item:any)=>({workspace:item.workspace.toLowerCase(),cash_in:item.cash_in,cash_out:item.cash_out,net_cash_flow:money(item.cash_in-item.cash_out)})) };
  }

  async profitLoss(actor: FinanceActor, filters: FinanceFilters) {
    const ctx=await this.context(actor,filters); const values=await this.classification(ctx); const breakdown=await Promise.all(ctx.access.units.filter(unit=>ctx.unitIds.includes(unit.id)).map(async unit=>({workspace:unit.code.toLowerCase(),...(await this.classification(ctx,[unit.id]))})));
    const result=money(values.income-values.expense+values.expense_reversal-values.income_reversal);
    return { currency_code:ctx.currency,period:ctx.period,basis:'basis transaksi kas; bukan laporan akrual/statutori',income:values.income,expense:values.expense,expense_reversal:values.expense_reversal,income_reversal:values.income_reversal,operating_result:result,breakdown:breakdown.map((item:any)=>({...item,operating_result:money(item.income-item.expense+item.expense_reversal-item.income_reversal)})) };
  }

  async receivables(actor: FinanceActor, filters: FinanceFilters) {
    const ctx=await this.context(actor,filters); if(!ctx.unitIds.length)return {items:[],totals:[]}; const [rows]:any=await pool.execute(`SELECT i.id,i.invoice_number source_code,i.issue_date,i.due_date,i.status_code,i.currency_code,i.total_amount,i.paid_amount,i.balance_due,p.display_name counterparty,bu.code workspace,DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+07:00')) today FROM invoices i JOIN business_units bu ON bu.id=i.business_unit_id LEFT JOIN parties p ON p.id=i.party_id WHERE i.organization_id=? AND i.business_unit_id IN (${placeholders(ctx.unitIds)}) AND i.balance_due>0.005 AND i.status_code NOT IN ('void','refunded')${filters.currency?' AND i.currency_code=?':''} ORDER BY i.due_date IS NULL,i.due_date,i.id`,[ctx.access.organizationId,...ctx.unitIds,...(filters.currency?[ctx.currency]:[])]); const items=asMoneyRows(rows).map((row:any)=>({...row,source:'invoice',source_url:row.workspace==='CRAFT'?'/app/craft/finance/receivables':'/app/studio/billing/outstanding',days_overdue:row.due_date?Math.max(0,Math.round((new Date(`${row.today}T00:00:00Z`).getTime()-new Date(`${String(row.due_date).slice(0,10)}T00:00:00Z`).getTime())/86_400_000)):0})); return {items,totals:this.currencyTotals(items,'balance_due')};
  }

  async payables(actor: FinanceActor, filters: FinanceFilters) {
    const ctx=await this.context(actor,filters); if(!ctx.unitIds.length)return {items:[],totals:[]}; const currencyClause=filters.currency?' AND currency_code=?':''; const currencyValues=filters.currency?[ctx.currency]:[];
    const [suppliers,expenses,assignments]:any=await Promise.all([
      pool.execute(`SELECT si.id,si.supplier_invoice_number source_code,si.invoice_date,si.due_date,si.status_code,si.currency_code,si.total_amount,si.paid_amount,si.balance_due,p.display_name counterparty,bu.code workspace FROM supplier_invoices si JOIN business_units bu ON bu.id=si.business_unit_id LEFT JOIN parties p ON p.id=si.supplier_party_id WHERE si.business_unit_id IN (${placeholders(ctx.unitIds)}) AND si.balance_due>0.005 AND si.status_code NOT IN ('paid','void')${currencyClause}`,[...ctx.unitIds,...currencyValues]),
      pool.execute(`SELECT e.id,e.expense_code source_code,e.expense_date invoice_date,NULL due_date,e.status_code,e.currency_code,(e.amount+e.tax_amount) total_amount,0 paid_amount,(e.amount+e.tax_amount) balance_due,p.display_name counterparty,bu.code workspace FROM expenses e JOIN business_units bu ON bu.id=e.business_unit_id LEFT JOIN parties p ON p.id=e.party_id WHERE e.organization_id=? AND e.business_unit_id IN (${placeholders(ctx.unitIds)}) AND e.status_code IN ('draft','approved')${filters.currency?' AND e.currency_code=?':''}`,[ctx.access.organizationId,...ctx.unitIds,...currencyValues]),
      pool.execute(`SELECT pea.id,CONCAT('ASSIGN-',pea.id) source_code,pea.start_date invoice_date,pea.end_date due_date,pea.payment_status_code status_code,sp.currency_code,pea.agreed_fee total_amount,COALESCE(paid.paid_amount,0) paid_amount,(pea.agreed_fee-COALESCE(paid.paid_amount,0)) balance_due,p.display_name counterparty,bu.code workspace FROM project_external_assignments pea JOIN studio_projects sp ON sp.id=pea.project_id AND sp.deleted_at IS NULL JOIN business_units bu ON bu.id=sp.business_unit_id LEFT JOIN parties p ON p.id=pea.party_id LEFT JOIN (SELECT source_code,SUM(amount) paid_amount FROM financial_transactions WHERE organization_id=? AND source_type='studio_external_payout' AND status_code='posted' GROUP BY source_code) paid ON paid.source_code=CONCAT('ASSIGN-',pea.id) WHERE bu.organization_id=? AND bu.code='STUDIO' AND sp.business_unit_id IN (${placeholders(ctx.unitIds)}) AND pea.agreed_fee-COALESCE(paid.paid_amount,0)>0.005${filters.currency?' AND sp.currency_code=?':''}`,[ctx.access.organizationId,ctx.access.organizationId,...ctx.unitIds,...currencyValues]),
    ]); const today=jakartaBusinessDate(); const items=asMoneyRows([...suppliers[0].map((row:any)=>({...row,source:'supplier_invoice',source_url:'/app/craft/procurement/invoices'})),...expenses[0].map((row:any)=>({...row,source:'expense',source_url:'/app/studio/finance/expenses'})),...assignments[0].map((row:any)=>({...row,source:'external_assignment',source_url:'/app/studio/finance/payables'}))]).map((row:any)=>({...row,days_overdue:row.due_date?Math.max(0,Math.round((new Date(`${today}T00:00:00Z`).getTime()-new Date(`${String(row.due_date).slice(0,10)}T00:00:00Z`).getTime())/86_400_000)):0})); return {items,totals:this.currencyTotals(items,'balance_due')};
  }

  private currencyTotals(items: any[], field: string) { const map=new Map<string,number>(); for(const item of items) map.set(item.currency_code,money((map.get(item.currency_code)||0)+Number(item[field]||0))); return [...map].map(([currency_code,value])=>({currency_code,value})); }

  async budgets(actor: FinanceActor, filters: FinanceFilters) { const ctx=await this.context(actor,filters); if(!ctx.unitIds.length)return []; const [rows]:any=await pool.execute(`SELECT b.*,bu.code workspace FROM budgets b LEFT JOIN business_units bu ON bu.id=b.business_unit_id WHERE b.organization_id=? AND (b.business_unit_id IS NULL OR b.business_unit_id IN (${placeholders(ctx.unitIds)})) ORDER BY b.period_start DESC,b.id DESC`,[ctx.access.organizationId,...ctx.unitIds]); return asMoneyRows(rows); }

  async journals(actor: FinanceActor, filters: FinanceFilters) { const ctx=await this.context(actor,filters); if(!ctx.unitIds.length)return pageResult([],filters.page,filters.limit,0); const page=filters.page,limit=Math.min(PAGE_CAP,filters.limit),offset=(page-1)*limit; const where=` WHERE j.organization_id=? AND j.business_unit_id IN (${placeholders(ctx.unitIds)})${filters.status?' AND j.status_code=?':''}${filters.q?' AND (j.journal_number LIKE ? OR j.description LIKE ?)':''}`; const params=[ctx.access.organizationId,...ctx.unitIds,...(filters.status?[filters.status]:[]),...(filters.q?[`%${filters.q}%`,`%${filters.q}%`]:[])]; const joins=' FROM journal_entries j JOIN business_units bu ON bu.id=j.business_unit_id LEFT JOIN users u ON u.id=j.created_by LEFT JOIN financial_periods fp ON fp.id=j.financial_period_id LEFT JOIN journal_lines jl ON jl.journal_entry_id=j.id'; const [rows,count]:any=await Promise.all([pool.execute(`SELECT j.id,j.journal_number,j.entry_date,j.description,j.source_type,j.source_id,j.status_code,bu.code workspace,fp.period_code,u.full_name actor,COALESCE(SUM(jl.debit_amount),0) debit_total,COALESCE(SUM(jl.credit_amount),0) credit_total ${joins}${where} GROUP BY j.id ORDER BY j.entry_date DESC,j.id DESC LIMIT ${limit} OFFSET ${offset}`,params),pool.execute(`SELECT COUNT(DISTINCT j.id) total ${joins}${where}`,params)]); const items=asMoneyRows(rows[0]).map((row:any)=>({...row,is_balanced:Math.abs(row.debit_total-row.credit_total)<=.01}));return pageResult(items,page,limit,Number(count[0][0]?.total||0)); }

  async journal(actor: FinanceActor, id: number) { const access=await unifiedFinanceAccess.resolve(actor),ids=unifiedFinanceAccess.ids(access);if(!ids.length)throw new AppError(404,'JOURNAL_NOT_FOUND','Jurnal tidak ditemukan.');const [headers]:any=await pool.execute(`SELECT j.*,bu.code workspace,fp.period_code,u.full_name actor FROM journal_entries j JOIN business_units bu ON bu.id=j.business_unit_id LEFT JOIN financial_periods fp ON fp.id=j.financial_period_id LEFT JOIN users u ON u.id=j.created_by WHERE j.id=? AND j.organization_id=? AND j.business_unit_id IN (${placeholders(ids)}) LIMIT 1`,[id,access.organizationId,...ids]);if(!headers.length)throw new AppError(404,'JOURNAL_NOT_FOUND','Jurnal tidak ditemukan.');const [lines]:any=await pool.execute(`SELECT jl.*,coa.account_code,coa.account_name,p.display_name party_name FROM journal_lines jl JOIN chart_of_accounts coa ON coa.id=jl.coa_account_id LEFT JOIN parties p ON p.id=jl.party_id WHERE jl.journal_entry_id=? ORDER BY jl.sort_order,jl.id`,[id]);const normalized=asMoneyRows(lines);const debit=money(normalized.reduce((sum:number,line:any)=>sum+line.debit_amount,0)),credit=money(normalized.reduce((sum:number,line:any)=>sum+line.credit_amount,0));return {...headers[0],lines:normalized,debit_total:debit,credit_total:credit,is_balanced:Math.abs(debit-credit)<=.01}; }

  async periods(actor: FinanceActor) { const access=await unifiedFinanceAccess.resolve(actor);const [rows]:any=await pool.execute(`SELECT fp.*,u.full_name closed_by_name FROM financial_periods fp LEFT JOIN users u ON u.id=fp.closed_by WHERE fp.organization_id=? ORDER BY fp.start_date DESC,fp.id DESC`,[access.organizationId]);return rows; }

  private async writablePeriod(connection: PoolConnection, organizationId: number, date: string) { const [rows]:any=await connection.execute(`SELECT id,status_code FROM financial_periods WHERE organization_id=? AND ? BETWEEN start_date AND end_date ORDER BY start_date DESC LIMIT 1 FOR UPDATE`,[organizationId,date]);if(!rows.length)return null;if(rows[0].status_code==='closed')throw new AppError(409,'FINANCIAL_PERIOD_CLOSED','Tanggal transaksi berada pada periode tertutup.');if(rows[0].status_code==='locked')throw new AppError(409,'FINANCIAL_PERIOD_LOCKED','Tanggal transaksi berada pada periode terkunci.');return Number(rows[0].id); }

  private async journalTransfer(connection: PoolConnection, data: { organizationId:number; businessUnitId:number; userId:number; date:string; description:string; amount:number; from:any; to:any; transferId:number; periodId:number|null }) { if(!data.from.coa_account_id||!data.to.coa_account_id)throw new AppError(409,'TRANSFER_JOURNAL_ACCOUNT_REQUIRED','Kedua akun kas transfer harus memiliki akun COA.');const [entry]:any=await connection.execute(`INSERT INTO journal_entries (organization_id,business_unit_id,financial_period_id,journal_number,entry_date,description,source_type,source_id,status_code,created_by,posted_by,posted_at) VALUES (?,?,?,?,?,'Transfer kas internal','internal_transfer',?,'posted',?,?,UTC_TIMESTAMP())`,[data.organizationId,data.businessUnitId,data.periodId,`TMP-${randomUUID()}`,data.date,data.transferId,data.userId,data.userId]);const id=Number(entry.insertId);const journalNumber=code('JRN',id);await connection.execute('UPDATE journal_entries SET journal_number=?,description=? WHERE id=?',[journalNumber,data.description,id]);await connection.execute(`INSERT INTO journal_lines (journal_entry_id,coa_account_id,description,debit_amount,credit_amount,sort_order) VALUES (?,?,?,?,?,0),(?,?,?,?,?,1)`,[id,data.to.coa_account_id,data.description,data.amount,0,id,data.from.coa_account_id,data.description,0,data.amount]);return id; }

  private async existingTransfer(access: FinanceAccess, data: any) { const [rows]:any=await pool.execute("SELECT t.*,DATE_FORMAT(CONVERT_TZ(t.transfer_date,'+00:00','+07:00'),'%Y-%m-%d') transfer_business_date FROM internal_transfers t WHERE t.organization_id=? AND t.idempotency_key=? LIMIT 1",[access.organizationId,data.idempotency_key]);if(!rows.length)return null;const row=rows[0];if(Number(row.from_treasury_account_id)!==Number(data.from_treasury_account_id)||Number(row.to_treasury_account_id)!==Number(data.to_treasury_account_id)||money(row.amount)!==money(data.amount)||row.transfer_business_date!==data.transfer_date||String(row.description||'').trim()!==String(data.description||'').trim())throw new AppError(409,'IDEMPOTENCY_KEY_CONFLICT','Kunci idempotensi sudah digunakan untuk transfer yang berbeda.');return {id:Number(row.id),transfer_code:row.transfer_code,idempotent:true}; }

  async createTransfer(actor: FinanceActor, data: any) { const access=await unifiedFinanceAccess.resolve(actor);if(data.from_treasury_account_id===data.to_treasury_account_id)throw new AppError(400,'SAME_TREASURY_TRANSFER','Akun asal dan tujuan transfer harus berbeda.');const existing=await this.existingTransfer(access,data);if(existing)return existing;const connection=await pool.getConnection();try{await connection.beginTransaction();const ids=[Number(data.from_treasury_account_id),Number(data.to_treasury_account_id)].sort((a,b)=>a-b);const [rows]:any=await connection.execute(`SELECT * FROM treasury_accounts WHERE id IN (?,?) AND organization_id=? AND is_active=1 ORDER BY id FOR UPDATE`,[ids[0],ids[1],access.organizationId]);if(rows.length!==2)throw new AppError(400,'INVALID_TRANSFER_TREASURY','Akun transfer tidak ditemukan, tidak aktif, atau bukan milik organisasi.');const from=rows.find((row:any)=>Number(row.id)===Number(data.from_treasury_account_id));const to=rows.find((row:any)=>Number(row.id)===Number(data.to_treasury_account_id));unifiedFinanceAccess.requireTransfer(access,Number(from.business_unit_id),Number(to.business_unit_id));if(from.currency_code!==to.currency_code)throw new AppError(400,'TRANSFER_CURRENCY_MISMATCH','Transfer hanya mendukung mata uang yang sama.');if(money(from.current_balance)+.01<money(data.amount))throw new AppError(409,'INSUFFICIENT_TREASURY_BALANCE','Saldo akun asal tidak mencukupi.');const dateSql=utcSql(jakartaDateStartUtc(data.transfer_date));const periodId=await this.writablePeriod(connection,access.organizationId,data.transfer_date);const [inserted]:any=await connection.execute(`INSERT INTO internal_transfers (organization_id,transfer_code,from_business_unit_id,to_business_unit_id,from_treasury_account_id,to_treasury_account_id,amount,currency_code,transfer_date,description,idempotency_key,status_code,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,'completed',?)`,[access.organizationId,`TMP-${randomUUID()}`,from.business_unit_id,to.business_unit_id,from.id,to.id,money(data.amount),from.currency_code,dateSql,data.description||null,data.idempotency_key,access.actorId]);const id=Number(inserted.insertId),transferCode=code('TRF',id);await connection.execute('UPDATE internal_transfers SET transfer_code=? WHERE id=?',[transferCode,id]);await connection.execute('UPDATE treasury_accounts SET current_balance=current_balance-? WHERE id=?',[money(data.amount),from.id]);await connection.execute('UPDATE treasury_accounts SET current_balance=current_balance+? WHERE id=?',[money(data.amount),to.id]);const shared=unifiedFinanceAccess.requireShared(access);const journalId=await this.journalTransfer(connection,{organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,date:dateSql,description:data.description||`Transfer ${transferCode}`,amount:money(data.amount),from,to,transferId:id,periodId});await connection.execute('UPDATE internal_transfers SET journal_entry_id=? WHERE id=?',[journalId,id]);await AuditService.write({organizationId:access.organizationId,businessUnitId:null,userId:access.actorId,moduleCode:'finance',actionCode:'finance.internal_transfer',entityType:'internal_transfer',entityId:id,entityCode:transferCode,description:`Transfer internal ${transferCode}.`,newValues:{from_treasury_account_id:from.id,to_treasury_account_id:to.id,amount:money(data.amount),currency_code:from.currency_code}},connection);await connection.commit();return {id,transfer_code:transferCode,journal_entry_id:journalId,idempotent:false};}catch(error:any){await connection.rollback();if(error?.code==='ER_DUP_ENTRY'){const retry=await this.existingTransfer(access,data);if(retry)return retry;throw new AppError(409,'IDEMPOTENCY_KEY_CONFLICT','Kunci idempotensi sudah digunakan.');}throw error;}finally{connection.release();} }

  private async existingSharedTransaction(access: FinanceAccess, data: any) { const [rows]:any=await pool.execute("SELECT ft.id,ft.transaction_code,ft.business_unit_id,ft.transaction_type,ft.treasury_account_id,ft.amount,ft.description,tc.code category_code,DATE_FORMAT(CONVERT_TZ(ft.transaction_date,'+00:00','+07:00'),'%Y-%m-%d') transaction_business_date FROM financial_transactions ft LEFT JOIN transaction_categories tc ON tc.id=ft.category_id WHERE ft.organization_id=? AND ft.idempotency_key=? LIMIT 1",[access.organizationId,data.idempotency_key]);if(!rows.length)return null;const row=rows[0];if(Number(row.business_unit_id)!==Number(access.byCode.SHARED?.id)||row.transaction_type!==(data.direction==='in'?'income':'expense')||Number(row.treasury_account_id)!==Number(data.treasury_account_id)||money(row.amount)!==money(data.amount)||row.category_code!==data.category_code||row.transaction_business_date!==data.transaction_date||String(row.description||'').trim()!==String(data.description||'').trim())throw new AppError(409,'IDEMPOTENCY_KEY_CONFLICT','Kunci idempotensi sudah digunakan untuk transaksi yang berbeda.');return {transactionId:Number(row.id),transactionCode:row.transaction_code,idempotent:true}; }

  async createSharedTransaction(actor: FinanceActor, data: any) { const access=await unifiedFinanceAccess.resolve(actor);const shared=unifiedFinanceAccess.requireShared(access);unifiedFinanceAccess.requireWrite(access,shared);const existing=await this.existingSharedTransaction(access,data);if(existing)return existing;const connection=await pool.getConnection();try{await connection.beginTransaction();const result=await this.posting.postCashMovement(connection,{organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,businessUnitCode:'SHARED'},{direction:data.direction,amount:data.amount,transactionDate:utcSql(jakartaDateStartUtc(data.transaction_date)),treasuryAccountId:data.treasury_account_id,categoryCode:data.category_code,description:data.description,partyId:data.party_id||null,sourceType:'finance_shared_manual',sourceCode:null,idempotencyKey:data.idempotency_key,enforceSourceIdempotency:false,auditAction:'finance.shared_transaction_create',auditEntityType:'financial_transaction'},{auditModule:'finance',auditAction:'finance.shared_transaction_create',idempotencyKey:data.idempotency_key});await connection.commit();return result;}catch(error:any){await connection.rollback();if(error?.code==='ER_DUP_ENTRY'){const retry=await this.existingSharedTransaction(access,data);if(retry)return retry;throw new AppError(409,'IDEMPOTENCY_KEY_CONFLICT','Kunci idempotensi sudah digunakan.');}throw error;}finally{connection.release();} }

  async reverseSharedTransaction(actor: FinanceActor, transactionId: number, data: any) { const access=await unifiedFinanceAccess.resolve(actor);const shared=unifiedFinanceAccess.requireShared(access);unifiedFinanceAccess.requireWrite(access,shared);const connection=await pool.getConnection();try{await connection.beginTransaction();const result=await this.posting.postCashMovementReversal(connection,{organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,businessUnitCode:'SHARED'},{originalTransactionId:transactionId,reversalDate:utcSql(jakartaDateStartUtc(data.reversal_date)),description:data.reason,idempotencyKey:data.idempotency_key},{auditModule:'finance',auditAction:'finance.shared_transaction_reverse',idempotencyKey:data.idempotency_key});await connection.commit();return result;}catch(error:any){await connection.rollback();if(error?.code==='ER_DUP_ENTRY')throw new AppError(409,'IDEMPOTENCY_KEY_CONFLICT','Kunci idempotensi sudah digunakan.');throw error;}finally{connection.release();} }

  async createSharedTreasury(actor: FinanceActor, data: any) { const access=await unifiedFinanceAccess.resolve(actor);const shared=unifiedFinanceAccess.requireShared(access);unifiedFinanceAccess.requireManage(access);const connection=await pool.getConnection();try{await connection.beginTransaction();let coa=data.coa_account_id||null;if(coa){const [accounts]:any=await connection.execute('SELECT id FROM chart_of_accounts WHERE id=? AND organization_id=? AND is_active=1 LIMIT 1',[coa,access.organizationId]);if(!accounts.length)throw new AppError(400,'INVALID_COA_ACCOUNT','Akun COA tidak valid.');}else{const [accounts]:any=await connection.execute("SELECT id FROM chart_of_accounts WHERE organization_id=? AND account_code='1000' AND is_active=1 ORDER BY business_unit_id IS NULL DESC LIMIT 1",[access.organizationId]);coa=accounts[0]?.id||null;}const [inserted]:any=await connection.execute(`INSERT INTO treasury_accounts (organization_id,business_unit_id,coa_account_id,account_code,name,account_type,provider_name,account_number_masked,currency_code,opening_balance,current_balance) VALUES (?,?,?,?,?,?,?,?,?,?,0)`,[access.organizationId,shared.id,coa,`TMP-${randomUUID()}`,data.name,data.account_type,data.provider_name||null,data.account_number_masked||null,data.currency_code,data.opening_balance]);const id=Number(inserted.insertId),accountCode=code('TRS',id);await connection.execute('UPDATE treasury_accounts SET account_code=? WHERE id=?',[accountCode,id]);if(money(data.opening_balance)>0)await this.posting.postTreasuryOpening(connection,{organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,businessUnitCode:'SHARED'},{treasuryAccountId:id,amount:data.opening_balance,date:new Date().toISOString().slice(0,23).replace('T',' '),description:`Saldo awal ${data.name}`},{auditModule:'finance',auditAction:'finance.treasury_opening',entityCode:accountCode});await AuditService.write({organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,moduleCode:'finance',actionCode:'finance.treasury_create',entityType:'treasury_account',entityId:id,entityCode:accountCode,description:`Membuat akun kas Shared ${accountCode}.`},connection);await connection.commit();return {id,account_code:accountCode};}catch(error){await connection.rollback();throw error;}finally{connection.release();} }

  async setSharedTreasuryStatus(actor: FinanceActor, id: number, active: boolean) { const access=await unifiedFinanceAccess.resolve(actor),shared=unifiedFinanceAccess.requireShared(access);unifiedFinanceAccess.requireManage(access);const connection=await pool.getConnection();try{await connection.beginTransaction();const [rows]:any=await connection.execute('SELECT id,account_code,current_balance,is_active FROM treasury_accounts WHERE id=? AND organization_id=? AND business_unit_id=? FOR UPDATE',[id,access.organizationId,shared.id]);if(!rows.length)throw new AppError(404,'TREASURY_NOT_FOUND','Akun kas Shared tidak ditemukan.');if(!active&&Math.abs(money(rows[0].current_balance))>.01)throw new AppError(409,'TREASURY_NON_ZERO_BALANCE','Akun bersaldo tidak dapat dinonaktifkan.');await connection.execute('UPDATE treasury_accounts SET is_active=? WHERE id=?',[active?1:0,id]);await AuditService.write({organizationId:access.organizationId,businessUnitId:shared.id,userId:access.actorId,moduleCode:'finance',actionCode:'finance.treasury_status_change',entityType:'treasury_account',entityId:id,entityCode:rows[0].account_code,description:'Memperbarui status akun kas Shared.',oldValues:{is_active:Boolean(rows[0].is_active)},newValues:{is_active:active}},connection);await connection.commit();return{id,is_active:active};}catch(error){await connection.rollback();throw error;}finally{connection.release();} }

  async createPeriod(actor: FinanceActor, data: any) { const access=await unifiedFinanceAccess.resolve(actor);unifiedFinanceAccess.requireManage(access);if(data.end_date<data.start_date)throw new AppError(400,'FINANCIAL_PERIOD_INVALID_RANGE','Tanggal akhir periode harus setelah tanggal mulai.');const connection=await pool.getConnection();try{await connection.beginTransaction();const [overlaps]:any=await connection.execute(`SELECT id FROM financial_periods WHERE organization_id=? AND start_date<=? AND end_date>=? FOR UPDATE`,[access.organizationId,data.end_date,data.start_date]);if(overlaps.length)throw new AppError(409,'FINANCIAL_PERIOD_OVERLAP','Periode keuangan tidak boleh tumpang tindih.');const [exists]:any=await connection.execute('SELECT id FROM financial_periods WHERE organization_id=? AND period_code=? LIMIT 1 FOR UPDATE',[access.organizationId,data.period_code]);if(exists.length)throw new AppError(409,'FINANCIAL_PERIOD_EXISTS','Kode periode sudah digunakan.');const [result]:any=await connection.execute(`INSERT INTO financial_periods (organization_id,period_code,start_date,end_date,status_code) VALUES (?,?,?,?,'open')`,[access.organizationId,data.period_code,data.start_date,data.end_date]);const id=Number(result.insertId);await AuditService.write({organizationId:access.organizationId,businessUnitId:null,userId:access.actorId,moduleCode:'finance',actionCode:'finance.period_create',entityType:'financial_period',entityId:id,entityCode:data.period_code,description:`Membuat periode keuangan ${data.period_code}.`},connection);await connection.commit();return{id,period_code:data.period_code};}catch(error){await connection.rollback();throw error;}finally{connection.release();} }

  async closePeriod(actor: FinanceActor, id: number, reason: string) { const access=await unifiedFinanceAccess.resolve(actor);unifiedFinanceAccess.requireManage(access);const connection=await pool.getConnection();try{await connection.beginTransaction();const [periods]:any=await connection.execute('SELECT * FROM financial_periods WHERE id=? AND organization_id=? FOR UPDATE',[id,access.organizationId]);if(!periods.length)throw new AppError(404,'FINANCIAL_PERIOD_NOT_FOUND','Periode tidak ditemukan.');if(periods[0].status_code==='locked')throw new AppError(409,'FINANCIAL_PERIOD_LOCKED','Periode terkunci tidak dapat ditutup ulang.');const [unbalanced]:any=await connection.execute(`SELECT j.id FROM journal_entries j JOIN journal_lines l ON l.journal_entry_id=j.id WHERE j.financial_period_id=? GROUP BY j.id HAVING ABS(SUM(l.debit_amount)-SUM(l.credit_amount))>.01 LIMIT 1`,[id]);if(unbalanced.length)throw new AppError(409,'JOURNAL_UNBALANCED','Periode berisi jurnal tidak seimbang.');await connection.execute(`UPDATE financial_periods SET status_code='closed',closed_by=?,closed_at=UTC_TIMESTAMP(3) WHERE id=?`,[access.actorId,id]);await AuditService.write({organizationId:access.organizationId,businessUnitId:null,userId:access.actorId,moduleCode:'finance',actionCode:'finance.period_close',entityType:'financial_period',entityId:id,entityCode:periods[0].period_code,description:reason},connection);await connection.commit();return{id,status_code:'closed'};}catch(error){await connection.rollback();throw error;}finally{connection.release();} }

  async reopenPeriod(actor: FinanceActor, id: number, reason: string) { const access=await unifiedFinanceAccess.resolve(actor);unifiedFinanceAccess.requireManage(access);const connection=await pool.getConnection();try{await connection.beginTransaction();const [periods]:any=await connection.execute('SELECT * FROM financial_periods WHERE id=? AND organization_id=? FOR UPDATE',[id,access.organizationId]);if(!periods.length)throw new AppError(404,'FINANCIAL_PERIOD_NOT_FOUND','Periode tidak ditemukan.');if(periods[0].status_code==='locked')throw new AppError(409,'FINANCIAL_PERIOD_LOCKED','Periode terkunci tidak dapat dibuka kembali.');if(periods[0].status_code!=='closed')throw new AppError(409,'FINANCIAL_PERIOD_NOT_CLOSED','Hanya periode tertutup yang dapat dibuka kembali.');await connection.execute(`UPDATE financial_periods SET status_code='open',closed_by=NULL,closed_at=NULL WHERE id=?`,[id]);await AuditService.write({organizationId:access.organizationId,businessUnitId:null,userId:access.actorId,moduleCode:'finance',actionCode:'finance.period_reopen',entityType:'financial_period',entityId:id,entityCode:periods[0].period_code,description:reason},connection);await connection.commit();return{id,status_code:'open'};}catch(error){await connection.rollback();throw error;}finally{connection.release();} }
}

export const unifiedFinanceService = new UnifiedFinanceService();
